import { CommonModule } from '@angular/common';
import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { AddressResponse, CustomerResponse } from '../../../core/models/models';
import { AccountService } from '../../../core/services/account.service';
import { AuthService } from '../../../core/services/auth.service';
import { AppIconComponent } from '../../../shared/components/icon/icon';

@Component({selector:'app-account',standalone:true,imports:[CommonModule,FormsModule,RouterLink,AppIconComponent],template:`
<div class="bg-paper"><div class="site-container page-shell">
<header class="page-header"><p class="eyebrow">Tài khoản</p><h1 class="page-title">Thông tin cá nhân</h1><p class="page-description">Quản lý hồ sơ, địa chỉ giao hàng và mật khẩu của bạn.</p></header>
<div class="grid gap-10 lg:grid-cols-[240px_minmax(0,1fr)] lg:gap-14">
<nav class="h-fit space-y-1.5 rounded-xl border border-border bg-surface p-3 lg:sticky lg:top-28 lg:self-start">
  <button class="flex w-full items-center gap-2.5 rounded-lg px-3 py-2.5 text-left text-sm transition-colors" [class.bg-cream]="tab()==='profile'" [class.font-semibold]="tab()==='profile'" (click)="tab.set('profile')"><app-icon name="user" class="h-4 w-4 text-primary"/>Hồ sơ</button>
  <button class="flex w-full items-center gap-2.5 rounded-lg px-3 py-2.5 text-left text-sm transition-colors" [class.bg-cream]="tab()==='addresses'" [class.font-semibold]="tab()==='addresses'" (click)="tab.set('addresses')"><app-icon name="map-pin" class="h-4 w-4 text-primary"/>Địa chỉ giao hàng</button>
  <button class="flex w-full items-center gap-2.5 rounded-lg px-3 py-2.5 text-left text-sm transition-colors" [class.bg-cream]="tab()==='password'" [class.font-semibold]="tab()==='password'" (click)="tab.set('password')"><app-icon name="shield" class="h-4 w-4 text-primary"/>Đổi mật khẩu</button>
  <a routerLink="/orders" class="flex items-center gap-2.5 rounded-lg px-3 py-2.5 text-sm text-body transition-colors hover:bg-cream"><app-icon name="package" class="h-4 w-4 text-primary"/>Đơn hàng</a>
  <a routerLink="/wishlist" class="flex items-center gap-2.5 rounded-lg px-3 py-2.5 text-sm text-body transition-colors hover:bg-cream"><app-icon name="heart" class="h-4 w-4 text-primary"/>Sách đã lưu</a>
</nav>
<main>
@if(loading()){<div class="skeleton h-72 rounded-xl"></div>}@else if(tab()==='profile'){
<form (submit)="saveProfile($event)" class="space-y-7"><div><h2 class="font-serif text-2xl font-semibold">Hồ sơ</h2><p class="mt-1.5 text-sm text-muted">Thông tin này được dùng để nhận diện tài khoản và hỗ trợ đơn hàng.</p></div><div class="grid gap-4 sm:grid-cols-2"><label><span class="field-label">Họ</span><input class="field" [(ngModel)]="form.lastName" name="lastName" required/></label><label><span class="field-label">Tên</span><input class="field" [(ngModel)]="form.firstName" name="firstName" required/></label><label><span class="field-label">Tên đệm</span><input class="field" [(ngModel)]="form.middleName" name="middleName"/></label><label><span class="field-label">Email</span><input class="field" type="email" [(ngModel)]="form.email" name="email"/></label><label><span class="field-label">Điện thoại</span><input class="field" [(ngModel)]="form.phone" name="phone"/></label><label><span class="field-label">Ngày sinh</span><input class="field" type="date" [(ngModel)]="form.birthDate" name="birthDate"/></label><label><span class="field-label">Giới tính</span><select class="field" [(ngModel)]="form.gender" name="gender"><option value="">Chưa chọn</option><option value="Nam">Nam</option><option value="Nu">Nữ</option><option value="Khac">Khác</option></select></label></div><label><span class="field-label">Địa chỉ liên hệ</span><textarea class="field min-h-24" [(ngModel)]="form.address" name="address"></textarea></label>@if(message()){<p class="text-sm" [class.text-danger]="isError()" [class.text-success]="!isError()">{{message()}}</p>}<button class="btn-primary" [disabled]="saving()">{{saving()?'Đang lưu...':'Lưu thay đổi'}}</button></form>
}@else if(tab()==='addresses'){
<section><div class="flex items-end justify-between gap-4"><div><h2 class="font-serif text-2xl font-semibold">Địa chỉ giao hàng</h2><p class="mt-1.5 text-sm text-muted">Địa chỉ đã dùng trong đơn hàng cũ được giữ lại để bảo toàn lịch sử.</p></div></div><div class="mt-6 divide-y divide-border border-y border-border">@for(a of addresses();track a.addressId){<div class="flex items-center gap-4 py-4"><app-icon name="map-pin" class="h-4 w-4 shrink-0 text-primary"/><p class="flex-1 text-sm leading-6">{{a.address}}</p><button class="text-sm font-medium text-primary hover:text-primary-dark" (click)="editAddress(a)">Sửa</button><button class="text-sm font-medium text-danger hover:text-[#92332e]" (click)="deleteAddress(a.addressId)">Xóa</button></div>}@empty{<p class="py-6 text-sm text-muted">Chưa có địa chỉ nào.</p>}</div><div class="mt-6 rounded-xl border border-border bg-surface p-6"><h3 class="font-serif text-lg font-semibold">{{editingAddressId()?'Sửa địa chỉ':'Thêm địa chỉ'}}</h3><textarea class="field mt-4 min-h-24" [(ngModel)]="addressText" placeholder="Nhập đầy đủ địa chỉ nhận hàng"></textarea><div class="mt-4 flex gap-2"><button class="btn-primary" (click)="saveAddress()" [disabled]="!addressText.trim()">{{editingAddressId()?'Lưu địa chỉ':'Thêm địa chỉ'}}</button>@if(editingAddressId()){<button class="btn-secondary" (click)="cancelAddressEdit()">Hủy</button>}</div>@if(addressMessage()){<p class="mt-3 text-sm text-danger">{{addressMessage()}}</p>}</div></section>
}@else{
<form (submit)="changePassword($event)" class="max-w-lg space-y-5"><div><h2 class="font-serif text-2xl font-semibold">Đổi mật khẩu</h2><p class="mt-1.5 text-sm text-muted">Mật khẩu mới nên có ít nhất 6 ký tự.</p></div><label><span class="field-label">Mật khẩu hiện tại</span><input class="field" type="password" [(ngModel)]="password.oldPassword" name="oldPassword" required/></label><label><span class="field-label">Mật khẩu mới</span><input class="field" type="password" [(ngModel)]="password.newPassword" name="newPassword" required/></label><label><span class="field-label">Nhập lại mật khẩu mới</span><input class="field" type="password" [(ngModel)]="password.confirmNewPassword" name="confirm" required/></label>@if(passwordMessage()){<p class="text-sm" [class.text-danger]="passwordError()" [class.text-success]="!passwordError()">{{passwordMessage()}}</p>}<button class="btn-primary">Đổi mật khẩu</button></form>
}
</main></div></div></div>`})
export class AccountComponent implements OnInit{
  private account=inject(AccountService);private auth=inject(AuthService);tab=signal<'profile'|'addresses'|'password'>('profile');loading=signal(true);saving=signal(false);message=signal('');isError=signal(false);addresses=signal<AddressResponse[]>([]);editingAddressId=signal<number|undefined>(undefined);addressText='';addressMessage=signal('');password={oldPassword:'',newPassword:'',confirmNewPassword:''};passwordMessage=signal('');passwordError=signal(false);form:Partial<CustomerResponse>={};
  ngOnInit(){this.account.getAccount().subscribe({next:r=>{if(r.data){this.form={...r.data,birthDate:r.data.birthDate?.slice(0,10)};this.auth.currentUser.set(r.data);}this.loading.set(false);},error:()=>this.loading.set(false)});this.loadAddresses();}
  saveProfile(e:Event){e.preventDefault();this.saving.set(true);this.account.updateProfile(this.form).subscribe({next:r=>{if(r.data){this.form={...r.data,birthDate:r.data.birthDate?.slice(0,10)};this.auth.currentUser.set(r.data);}this.message.set(r.message||'Đã lưu thay đổi.');this.isError.set(false);this.saving.set(false);},error:err=>{this.message.set(err.error?.message||'Không thể cập nhật.');this.isError.set(true);this.saving.set(false);}});}
  loadAddresses(){this.account.getAddresses().subscribe(a=>this.addresses.set(a));}
  editAddress(a:AddressResponse){this.editingAddressId.set(a.addressId);this.addressText=a.address;this.addressMessage.set('');}
  cancelAddressEdit(){this.editingAddressId.set(undefined);this.addressText='';}
  saveAddress(){const t=this.addressText.trim();if(!t)return;const id=this.editingAddressId();const request=id?this.account.updateAddress(id,t):this.account.addAddress(t);request.subscribe({next:()=>{this.loadAddresses();this.cancelAddressEdit();this.addressMessage.set('');},error:err=>this.addressMessage.set(err.error?.message||'Không thể lưu địa chỉ.')});}
  deleteAddress(id:number){if(!confirm('Xóa địa chỉ này?'))return;this.account.deleteAddress(id).subscribe({next:()=>this.loadAddresses(),error:err=>this.addressMessage.set(err.error?.message||'Không thể xóa địa chỉ.')});}
  changePassword(e:Event){e.preventDefault();if(this.password.newPassword!==this.password.confirmNewPassword){this.passwordMessage.set('Mật khẩu xác nhận không khớp.');this.passwordError.set(true);return;}this.account.changePassword(this.password).subscribe({next:r=>{this.passwordMessage.set(r.message||'Đổi mật khẩu thành công.');this.passwordError.set(false);this.password={oldPassword:'',newPassword:'',confirmNewPassword:''};},error:err=>{this.passwordMessage.set(err.error?.message||'Không thể đổi mật khẩu.');this.passwordError.set(true);}});}
}